import type { Card } from '../types'

// ============================================================================
// EL MAZO — aquí vive todo el contenido jugable del juego.
// Este es el ÚNICO archivo que hace falta tocar para añadir o editar cartas.
// (Las cartas de "final de partida" viven aparte, en cards.ts, porque llevan
// algo de lógica de código — no hace falta tocarlas para añadir contenido.)
// ============================================================================
//
// PLANTILLA — copia este bloque, pégalo donde quieras dentro del array de
// abajo, y rellena los huecos:
//
//   {
//     id: 'mi_carta_nueva',      // único en todo el mazo, minúsculas y guion_bajo
//     phase: 1,                   // 1=luna de miel · 2=desgaste · 3=crisis · 4=vísperas electorales
//     character: 'El Personaje',  // quién "habla" en la carta
//     text: 'Texto de la situación...',
//     left:  { text: 'Opción izquierda', effects: { medios: -1, caja: 1 } },
//     right: { text: 'Opción derecha',   effects: { gobierno: 2 } },
//   },
//
// Reglas rápidas:
// - Stats válidas dentro de `effects`: medios, gobierno, calle, caja (0 a 10).
//   Cada personaje tiene SU indicador de cabecera y sus cartas deberían
//   tocarlo siempre (ver la tabla en types.ts): así, viendo quién habla, ya
//   se sabe qué está en juego. Es como funciona Reigns.
// - No hace falta poner las 4 stats en cada choice, solo las que cambian.
// - Los valores de `effects` van normalmente entre -3 y +3.
// - `phase` decide a partir de qué turno puede salir la carta:
//     1 = luna de miel      (turno 1+,  favores pequeños, anecdótico)
//     2 = desgaste          (turno 9+,  empiezan las grietas)
//     3 = crisis            (turno 21+, la unidad anticorrupción, jueces, fiscal general)
//     4 = vísperas electorales (turno 36+, indultos, moción de censura)
// - El `id` no puede empezar por "final_" — ese prefijo está reservado para
//   las cartas de final de partida (cards.ts).
// - Después de editar, corre `npm run validate-cards` para comprobar que todo
//   está bien (ids duplicados, stats mal escritas, valores raros...) antes de
//   `npm run dev`. Te avisa de qué carta y qué línea tiene el problema.
//
// ============================================================================

