    text: 'Balance del año: aguantamos, no se ha caído nada gordo y hasta hay quien nos defiende sin cobrar. Toca decidir cómo vendemos esto en enero.',
    left: { text: 'Un año más de perfil bajo', effects: { medios: 1, calle: -1 }, moralidad: 1 },
